argv:
$ids=@('agent-pc-executor','agent-creator','agent-media','agent-growth','agent-bridge-reliability');
$assign=Invoke-RestMethod -Uri 'http://127.0.0.1:17448/api/supervisor-watchdog/agent-assignments' -TimeoutSec 8;
$chat=Invoke-RestMethod -Uri 'http://127.0.0.1:17448/api/supervisor-watchdog/managed-chats?inspect=1' -TimeoutSec 12;
$out=@();
foreach($id in $ids){
  $rows=@($assign.assignments)|Where-Object{$_.targetChatId -eq $id}|Sort-Object createdAt;
  $last=$rows|Select-Object -Last 1;
  $c=@($chat.chats)|Where-Object{$_.id -eq $id}|Select-Object -First 1;
  $out += [pscustomobject]@{
    id=$id; chatStatus=$c.status; generating=$c.generating; draftPresent=$c.draftPresent; openTabs=$c.openTabs;
    activeAssignmentCount=$c.activeAssignmentCount; assignmentId=$last.id; assignmentState=$last.state;
    dispatchCount=$last.dispatchCount; repo=$last.repository; branch=$last.branch; currentHead=$last.currentHead;
    lastDiagnostic=$last.lastDiagnostic
  }
}
$out|ConvertTo-Json -Compress -Depth 6
